function getEventAuthorityPda(programId: PublicKey): PublicKey {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("__event_authority")],
    programId,
  )[0];
}

function bondingCurvePda(mint: PublicKeyInitData): PublicKey {
  return pumpPda([
    Buffer.from("bonding-curve"),
    new PublicKey(mint).toBuffer(),
  ]);
}

function bondingCurveV2Pda(mint: PublicKeyInitData): PublicKey {
  return pumpPda([
    Buffer.from("bonding-curve-v2"),
    new PublicKey(mint).toBuffer(),
  ]);
}

function creatorVaultPda(creator: PublicKey) {
  return pumpPda([Buffer.from("creator-vault"), creator.toBuffer()]);
}

function holderRewardsPda(mint: PublicKey): PublicKey {
  return pumpPda([Buffer.from("holder-rewards"), mint.toBuffer()]);
}

function pumpPoolAuthorityPda(mint: PublicKey): PublicKey {
  return pumpPda([Buffer.from("pool-authority"), mint.toBuffer()]);
}

function canonicalPumpPoolPda(mint: PublicKey): PublicKey {
  return poolPda(
    CANONICAL_POOL_INDEX,
    pumpPoolAuthorityPda(mint),
    mint,
    NATIVE_MINT,
  );
}

function canonicalPumpPoolPdaWithQuote(
  mint: PublicKey,
  quoteMint: PublicKey,
): PublicKey {
  return poolPda(
    CANONICAL_POOL_INDEX,
    pumpPoolAuthorityPda(mint),
    mint,
    quoteMint,
  );
}

function boostVaultAuthorityPda(pool: PublicKey): PublicKey {
  return pumpAmmPda([Buffer.from("boost_vault"), pool.toBuffer()]);
}

function userVolumeAccumulatorPda(
  user: PublicKey,
  program = PUMP_PROGRAM_ID,
): PublicKey {
  if (program.equals(PUMP_PROGRAM_ID)) {
    return pumpPda([Buffer.from("user_volume_accumulator"), user.toBuffer()]);
  }
  return pumpAmmPda([Buffer.from("user_volume_accumulator"), user.toBuffer()]);
}

